		'scratch-removal' => [ 'Acrylic Aquarium Scratch Removal & Restoration | Acrylic Pros', 'We specialize in removing scratches off your aquarium with or without water, 100% fish and coral safe! The materials we use to polish acrylic have been used for over 20 years in the aquarium industry.', 'Got Scratches? We Can Help! — Acrylic Pros', 'Acrylic Pros — restoring scratched acrylic to crystal-clear perfection.', 'scratch-02.jpeg' ],
		'services' => [ 'Aquarium Services — Custom Aquarium Design, Restoration & Installation | Acrylic Pros', 'Acrylic Pros — expert aquarium services since 2005: scratch removal, acrylic pool panels, custom builds & installations, acrylic sign fabrication, pond design and construction, aquarium relocations, 24hr emergency services, maintenance services and livestock.', 'Aquarium Services — Acrylic Pros', 'Custom aquarium design, restoration & installation throughout Southern California and nationwide. Since 2005.', 'coral-closeup-header.jpg' ],
		'sharks' => [ 'Sharks | Acrylic Pros', 'We carry a large selection of sharks, from horn shark, white tip reef shark, smooth hound shark, bamboo shark, Epaulette shark, and more. Nationwide Shipping.', 'Sharks — Acrylic Pros', 'We carry a large selection of sharks. Nationwide Shipping.', 'txtw546G9_8.jpg' ],
